// ============================================================
// Build Final Newsletter HTML
// Input: structured JSON from OpenAI primary or Gemini fallback (categories array)
// This node owns ALL HTML rendering �?LLM produces data only.
// ============================================================
const item = items[0].json;

// ── STEP 1: Extract raw text from any Gemini output format ──
let rawText = null;
for (const c of [item?.text, item?.output, item?.content?.parts?.[0]?.text,
                 item?.candidates?.[0]?.content?.parts?.[0]?.text, item?.response]) {
  if (typeof c === 'string' && c.trim().length > 10) { rawText = c.trim(); break; }
}
if (!rawText) {
  const find = (o, d) => {
    if (d > 5) return null;
    if (typeof o === 'string' && o.length > 30) return o;
    if (!o || typeof o !== 'object') return null;
    for (const v of Object.values(o)) { const r = find(v, d+1); if (r) return r; }
    return null;
  };
  rawText = find(item, 0);
}

// ── STEP 2: Parse JSON from LLM output ──────────────────────
let data = null;
if (rawText) {
  let t = rawText;
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) t = fence[1].trim();
  const s = t.indexOf('{'), e = t.lastIndexOf('}');
  if (s !== -1 && e !== -1) {
    const candidate = t.slice(s, e+1).replace(/,\s*([}\]])/g, '$1');
    try { data = JSON.parse(candidate); } catch(_) {}
  }
  if (!data) { try { data = JSON.parse(rawText); } catch(_) {} }
}

// ── STEP 3: Build date string ────────────────────────────────
const now = new Date();
const dateIT = data?.date || now.toLocaleDateString('it-IT', {weekday:'long', year:'numeric', month:'long', day:'numeric'});
const subjectDate = now.toLocaleDateString('it-IT', {day:'2-digit', month:'2-digit', year:'numeric'});

// ── STEP 4: Handle error / missing data ─────────────────────
// If primary/fallback LLM hits quota/rate limits, the nodes are configured with error outputs
// that carries the original pre-processed articles plus item.error. Build a
// deterministic fallback briefing instead of silently ending the workflow.
if (!data || data.error || !Array.isArray(data.categories) || data.categories.length === 0) {
  const fallbackArticles = Array.isArray(item?.articles) ? item.articles : [];
  if (fallbackArticles.length > 0) {
    const allowedOrder = [
      'Cybersecurity & Cyberwar',
      'AI & Machine Learning',
      'Big Tech & Industria Digitale',
      'Regolazione & Politiche Digitali',
      'Infrastrutture, Cloud & Chip',
      'Economia Tech & Mercati',
      'Società Digitale & Diritti',
    ];
    const classify = (a) => {
      const t = `${a.title || ''} ${a.content || ''} ${a.source || ''}`.toLowerCase();
      if (/hack|breach|ransom|malware|vulnerab|cve|cyber|security|threat|phishing|exploit|spy|token|oauth|claude code mcp/.test(t)) return 'Cybersecurity & Cyberwar';
      if (/ai|artificial intelligence|machine learning|llm|model|gemini|openai|anthropic|deepmind|agent|nvidia|gpu/.test(t)) return 'AI & Machine Learning';
      if (/cloud|datacenter|data center|chip|semiconductor|gpu|nvidia|infrastructure|server/.test(t)) return 'Infrastrutture, Cloud & Chip';
      if (/regulation|regol|privacy|antitrust|dma|ai act|govern|policy|ue|european|law/.test(t)) return 'Regolazione & Politiche Digitali';
      if (/market|funding|startup|ipo|layoff|acquisition|revenue|stock|invest/.test(t)) return 'Economia Tech & Mercati';
      if (/privacy|surveillance|rights|misinformation|social|society/.test(t)) return 'Società Digitale & Diritti';
      return 'Big Tech & Industria Digitale';
    };
    const summarize = (a) => {
      const text = (a.content || '').replace(/\s+/g, ' ').trim();
      if (!text) return 'Notizia selezionata dalle fonti monitorate; apri il link originale per i dettagli completi.';
      const words = text.split(/\s+/).slice(0, 45).join(' ');
      return words + (text.split(/\s+/).length > 45 ? '�? : '');
    };
    const buckets = Object.fromEntries(allowedOrder.map(c => [c, []]));
    const seen = new Set();
    for (const a of fallbackArticles) {
      if (!a?.title || !a?.link || seen.has(a.link)) continue;
      seen.add(a.link);
      const cat = classify(a);
      if (buckets[cat].length < 3) {
        buckets[cat].push({
          title: a.title,
          summary: summarize(a),
          source_name: a.source || 'Fonte originale',
          link: a.link,
        });
      }
      const selected = Object.values(buckets).reduce((n, xs) => n + xs.length, 0);
      if (selected >= 10) break;
    }
    data = {
      date: dateIT,
      fallback: true,
      fallback_reason: item?.error || 'LLM non disponibile',
      categories: allowedOrder.map(name => ({ name, articles: buckets[name] })).filter(c => c.articles.length > 0),
    };
  }
}

if (!data || data.error || !Array.isArray(data.categories) || data.categories.length === 0) {
  const errDetail = data?.error || item?.error || 'Nessuna categoria trovata';
  return [{
    json: {
      subject: `⚠️ Rassegna Tech ${subjectDate} �?Errore`,
      html: `<!DOCTYPE html><html lang="it"><body style="font-family:Arial;padding:20px">
        <h2>⚠️ Errore nella generazione della rassegna</h2>
        <p>${errDetail}</p>
        <pre style="font-size:11px;background:#f5f5f5;padding:10px">${(rawText||JSON.stringify(item)||'').substring(0,1000)}</pre>
      </body></html>`
    }
  }];
}

// ── STEP 5: Category icons map ───────────────────────────────
const ICONS = {
  'Cybersecurity & Cyberwar':        '🔐',
  'AI & Machine Learning':           '🤖',
  'Big Tech & Industria Digitale':   '🏢',
  'Regolazione & Politiche Digitali':'⚖️',
  'Infrastrutture, Cloud & Chip':    '🖥�?,
  'Economia Tech & Mercati':         '📈',
  'Società Digitale & Diritti':      '🌐',
};

// ── STEP 6: Build HTML sections ─────────────────────────────
const categorySections = data.categories.map(cat => {
  const icon = ICONS[cat.name] || '📌';
  const articles = (cat.articles || []).map(a => {
    const safeTitle   = (a.title   || '').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const safeSummary = (a.summary || '').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const safeName    = (a.source_name || '').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    // Only render link if it looks like a valid URL
    const isValidUrl  = /^https?:\/\/.+/.test(a.link || '');
    const sourceTag   = isValidUrl
      ? `<a href="${a.link}" target="_blank" rel="noopener" style="color:#2980b9;text-decoration:none">${safeName}</a>`
      : `<span style="color:#7f8c8d">${safeName}</span>`;
    return `
      <div style="border-left:3px solid #e74c3c;padding:10px 14px;margin-bottom:14px;background:#fafafa">
        <p style="margin:0 0 6px 0;font-weight:bold;font-size:14px;color:#2c3e50">${safeTitle}</p>
        <p style="margin:0 0 6px 0;font-size:13px;line-height:1.55;color:#444">${safeSummary}</p>
        <p style="margin:0;font-size:11px;color:#7f8c8d">Fonte: ${sourceTag}</p>
      </div>`;
  }).join('');

  return `
    <div style="margin-bottom:28px">
      <h2 style="color:#2c3e50;border-bottom:2px solid #e74c3c;padding-bottom:6px;font-size:16px;margin-bottom:14px">
        ${icon} ${cat.name}
      </h2>
      ${articles}
    </div>`;
}).join('');

const totalArticles = data.categories.reduce((n, c) => n + (c.articles||[]).length, 0);
const subject = `📰 Rassegna Tech & AI �?${subjectDate}`;

// ── STEP 7: Full HTML email ──────────────────────────────────
const html = `<!DOCTYPE html>
<html lang="it">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>${subject}</title>
</head>
<body style="margin:0;padding:0;background:#f0f2f5;font-family:Arial,Helvetica,sans-serif">
  <div style="max-width:680px;margin:24px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.10)">

    <!-- HEADER -->
    <div style="background:linear-gradient(135deg,#1a252f 0%,#2c3e50 100%);padding:28px 24px;text-align:center">
      <div style="font-size:11px;letter-spacing:2px;text-transform:uppercase;color:#95a5a6;margin-bottom:6px">Rassegna Quotidiana</div>
      <h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700">Tech & AI Briefing</h1>
      <div style="margin-top:8px;color:#bdc3c7;font-size:13px">${dateIT}</div>
    </div>

    <!-- SUMMARY BAR -->
    <div style="background:#2c3e50;padding:10px 24px;text-align:center">
      <span style="color:#ecf0f1;font-size:12px">${totalArticles} notizie selezionate · ${data.categories.length} categorie</span>
    </div>

    <!-- CONTENT -->
    <div style="padding:24px 28px">
      ${categorySections}
    </div>

    <!-- FOOTER -->
    <div style="background:#ecf0f1;padding:16px 24px;text-align:center;border-top:1px solid #dde1e4">
      <p style="margin:0;font-size:11px;color:#95a5a6">
        Rassegna generata automaticamente · ${dateIT}<br>
        Le notizie sono selezionate da fonti pubbliche. I link rimandano alle fonti originali.
      </p>
    </div>
  </div>
</body>
</html>`;

return [{ json: { subject, html } }];

// ============================================================
// Pre-processing: normalize, tag source, cap per-domain, deduplicate
// CVE feeds removed upstream �?no need to filter them here
// ============================================================
function domainLabel(url) {
  if (!url) return 'Unknown';
  let host;
  try {
    host = new URL(url).hostname.replace(/^www\./, '');
  } catch(_) {
    const m = url.match(/https?:\/\/([^\/]+)/);
    host = m ? m[1].replace(/^www\./, '') : 'unknown';
  }
  const map = {
    'feeds.feedburner.com':      (url.includes('TheHackersNews') || url.includes('thehackernews') ? 'The Hacker News'
                                 : url.includes('nvidiablog') ? 'NVIDIA'
                                 : url.includes('eset') ? 'ESET'
                                 : host),
    'cloudblog.withgoogle.com':  'Google Cloud Blog',
    'research.google':           'Google Research',
    'isc.sans.edu':              'SANS ISC',
    'nvidianews.nvidia.com':     'NVIDIA',
    'developer.nvidia.com':      'NVIDIA Developer',
    'news.mit.edu':              'MIT Technology Review',
    'blog.talosintelligence.com':'Cisco Talos',
    'feeds.arstechnica.com':     'Ars Technica',
    'feeds.reuters.com':         'Reuters',
    'thehackernews.com':         'The Hacker News',
    'krebsonsecurity.com':       'Krebs on Security',
    'darkreading.com':           'Dark Reading',
    'cybersecuritynews.com':     'Cybersecurity News',
    'cybersecurity360.it':       'Cybersecurity360',
    'ilsole24ore.com':           'Il Sole 24 Ore',
    'techcrunch.com':            'TechCrunch',
    'arstechnica.com':           'Ars Technica',
    'wired.com':                 'Wired',
    'theverge.com':              'The Verge',
    'reuters.com':               'Reuters',
    'anthropic.com':             'Anthropic',
    'deepmind.google':           'Google DeepMind',
    'openai.com':                'OpenAI',
    'checkpoint.com':            'Check Point Research',
  };
  return map[host] || host;
}

function simpleSimilarity(a, b) {
  const wa = new Set(a.toLowerCase().split(/\W+/).filter(w => w.length > 4));
  const wb = new Set(b.toLowerCase().split(/\W+/).filter(w => w.length > 4));
  if (wa.size === 0 || wb.size === 0) return 0;
  const inter = [...wa].filter(w => wb.has(w)).length;
  return inter / Math.max(wa.size, wb.size);
}

// Normalize and tag source
const allArticles = items
  .map(i => ({
    title:   (i.json.title || '').trim(),
    content: ((i.json.contentSnippet || i.json.content || '').trim()).substring(0, 500),
    link:    (i.json.link || '').trim(),
    isoDate: i.json.isoDate || '',
    source:  domainLabel(i.json.link || ''),
  }))
  .filter(a => a.title && a.link && a.link.startsWith('http'));

// Sort by date descending
allArticles.sort((a, b) => (b.isoDate > a.isoDate ? 1 : -1));

// Deduplicate by title similarity (>65% word overlap)
const deduped = [];
for (const art of allArticles) {
  const isDup = deduped.some(seen => simpleSimilarity(seen.title, art.title) > 0.65);
  if (!isDup) deduped.push(art);
}

// Cap: max 4 articles per source domain (avoid any single source dominating)
const domainCount = {};
const capped = [];
for (const art of deduped) {
  const key = art.source;
  domainCount[key] = (domainCount[key] || 0);
  if (domainCount[key] < 4) {
    capped.push(art);
    domainCount[key]++;
  }
}

return [{ json: { articles: capped, total: capped.length } }];
